(function(root,factory){const P=(typeof module==='object'&&module.exports)?require('./supplier-purchase-order.js'):root.MIRSupplierPO;const D=(typeof module==='object'&&module.exports)?require('./supplier-directory.js'):root.MIRSupplierDirectory;const api=factory(P,D);if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.MIRInventoryReorder=api;})(typeof window==='object'?window:null,function(P,D){
'use strict';
const clone=v=>JSON.parse(JSON.stringify(v));const text=v=>String(v??'').trim();
function assert(c,m){if(!c)throw new Error(m)}
function normalizePolicy(input={}){const p={itemId:text(input.itemId),reorderPoint:Number(input.reorderPoint),targetStock:Number(input.targetStock),preferredSupplierId:text(input.preferredSupplierId),supplierSku:text(input.supplierSku),unitCost:input.unitCost===''||input.unitCost==null?null:Number(input.unitCost),enabled:input.enabled!==false};assert(p.itemId,'Article requis');assert(Number.isFinite(p.reorderPoint)&&p.reorderPoint>=0,'Seuil réappro invalide');assert(Number.isFinite(p.targetStock)&&p.targetStock>=p.reorderPoint,'Stock cible invalide');if(p.unitCost!==null)assert(Number.isFinite(p.unitCost)&&p.unitCost>=0,'Coût de réappro invalide');return p}
function evaluateReorder(store,policies=[]){const catalogById=Object.fromEntries((store?.catalog||[]).map(i=>[i.id,i]));const needs=[];for(const raw of policies){const p=normalizePolicy(raw);if(!p.enabled)continue;const inv=store?.inventory?.[p.itemId];if(!inv)throw new Error(`Article inventaire inconnu: ${p.itemId}`);const available=(Number(inv.physical)||0)-(Number(inv.reserved)||0);if(available>p.reorderPoint+1e-9)continue;const quantity=Math.max(0,p.targetStock-available);if(quantity<=1e-9)continue;const item=catalogById[p.itemId]||{id:p.itemId,name:p.itemId,unit:'unité'};needs.push({itemId:p.itemId,name:item.name||p.itemId,unit:item.unit||'unité',physical:Number(inv.physical)||0,reserved:Number(inv.reserved)||0,available,reorderPoint:p.reorderPoint,targetStock:p.targetStock,quantity,preferredSupplierId:p.preferredSupplierId,supplierSku:p.supplierSku,unitCost:p.unitCost});}return needs}
function groupBySupplier(needs=[]){const groups=new Map(),unassigned=[];for(const n of needs){if(!n.preferredSupplierId){unassigned.push(clone(n));continue}if(!groups.has(n.preferredSupplierId))groups.set(n.preferredSupplierId,[]);groups.get(n.preferredSupplierId).push(clone(n))}return{groups:Object.fromEntries(groups),unassigned}}
function buildDraftPurchaseOrders(store,policies,directory,{project={},poNumberPrefix='AUTO',createdBy='MIR'}={}){assert(P&&D,'Modules fournisseur requis');const needs=evaluateReorder(store,policies);const grouped=groupBySupplier(needs);const drafts=[],blocked=[];for(const [supplierId,items] of Object.entries(grouped.groups)){const profile=D.getSupplier(directory,supplierId);if(!profile||profile.archived){blocked.push({supplierId,reason:'Fournisseur préféré introuvable ou archivé',items});continue}const supplier=D.toPurchaseOrderSupplier(profile);let po=P.createPurchaseOrder({poNumber:'',supplier,project:{...project,requestedBy:createdBy},currency:supplier.currency,metadata:{source:'inventory-reorder',generatedAt:new Date().toISOString()},lines:[]});for(const item of items)po=P.addLine(po,{supplierSku:item.supplierSku,description:`Réapprovisionnement — ${item.name}`,quantity:item.quantity,unit:item.unit,unitCost:item.unitCost,currency:supplier.currency,destination:'inventory',inventoryItemId:item.itemId,notes:`Disponible ${item.available}; seuil ${item.reorderPoint}; cible ${item.targetStock}`});drafts.push(po)}return{needs,drafts,blocked,unassigned:grouped.unassigned}}
function proposalSummary(result){return{needs:result.needs.length,draftOrders:result.drafts.length,blockedSupplierGroups:result.blocked.length,unassignedItems:result.unassigned.length,totalQuantity:result.needs.reduce((s,x)=>s+x.quantity,0)}}
return{normalizePolicy,evaluateReorder,groupBySupplier,buildDraftPurchaseOrders,proposalSummary};
});
